paths = glob.glob(os.path.join(ROOT, "**", "audit", "local_rewrite_cycles.json"), recursive=True)
print("num files:", len(paths))

total_items = 0
method_counts = {}
not_found_examples = []
fallback_low_overlap_examples = []  # overlap < 0.5, borderline
multi_clause_examples = []  # original_ng_sentence very long / contains multiple ';' or 'and' clauses combined w/ final_text sentence count mismatch
resolved_counts = {"resolved_true": 0, "resolved_false": 0, "human_review_required": 0}
family_counts = {"a_family": 0, "b_family": 0}

