for p in paths:
    try:
        with open(p, encoding="utf-8") as f:
            cycles = json.load(f)
    except Exception as e:
        continue
    fam = "b_family" if is_b_family(p) else "a_family"
    for cyc in cycles:
        for item in cyc.get("results", []):
            total_items += 1
            family_counts[fam] += 1
            lm = item.get("location_method", "MISSING")
            key = lm.split("(")[0]
            method_counts[key] = method_counts.get(key, 0) + 1
            if item.get("resolved"):
                resolved_counts["resolved_true"] += 1
