                        "path": p, "overlap": m.group(1),
                        "original_ng_sentence": item.get("original_ng_sentence"),
                    })
            orig = item.get("original_ng_sentence") or ""
            final = item.get("final_text") or ""
            # crude heuristic for multi-clause / sentence count mismatch: count of '. ' occurrences
            orig_periods = orig.count(". ") + orig.count(".\"")
            final_periods = final.count(". ") + final.count(".\"")
            if orig_periods != final_periods and len(multi_clause_examples) < 8:
                multi_clause_examples.append({
                    "path": p, "orig_periods": orig_periods, "final_periods": final_periods,
                    "original_ng_sentence": orig[:200], "final_text": final[:200] if final else None,
                })

