    "num_files": len(paths),
    "total_items": total_items,
    "family_counts": family_counts,
    "method_counts": method_counts,
    "resolved_counts": resolved_counts,
    "not_found_examples": not_found_examples,
    "fallback_low_overlap_examples": fallback_low_overlap_examples,
    "multi_clause_examples": multi_clause_examples,
}
out_path = (r"C:\Users\tensh\AppData\Local\Temp\claude\C--Users-tensh-eigo-radio"
            r"\294958fe-da6e-491c-8a02-4f864d8195c8\scratchpad\open141_a2_scan_result.json")
with open(out_path, "w", encoding="utf-8") as f:
    json.dump(summary, f, indent=2, ensure_ascii=False)

print(json.dumps({"total_items": total_items, "family_counts": family_counts,
                   "method_counts": method_counts, "resolved_counts": resolved_counts}, indent=2))

